style.css:
@-moz-document domain("pony.town") {
/* ⚠️ Main UI Panels & Backgrounds */
    .panel, .box, .menu, .sidebar, .modal-content, .dropdown-menu {
        background-color: #1a1914 !important; /* Deep dark charcoal yellow */
        border: 1px solid #d4af37 !important; /* Dark gold/yellow border */
        color: #f1ebd9 !important; /* Soft warm white text */
    }

    /* ➡️ Primary Buttons & Active Highlights */
    .btn-primary, .tab.active, .nav-link.active, .btn-success {
        background-image: none !important;
        background-color: #cc9c00 !important; /* Rich dark yellow */
        color: #111111 !important; /* Dark text for contrast */
        border: 1px solid #e6b000 !important;
        border-radius: 4px !important;
        text-shadow: none !important;
    }

    /* ? Secondary Buttons & Hover States */
    .btn-secondary, .btn-default, .tab:hover, .btn:hover {
        background-image: none !important;
        background-color: #332f20 !important; /* Dark brownish yellow */
        color: #ffdf7a !important; /* Vibrant dark yellow text */
        border: 1px solid #595033 !important;
    }

    /* ? Chat Log & Text Input Fields */
    input, textarea, select, .chat-log {
        background-color: #13120e !important; /* Almost pitch black yellow */
        color: #ffffff !important;
        border: 1px solid #595033 !important;
    }

    /* ✨ Text Links & Special Highlights */
    a, .text-primary {
        color: #e6b000 !important;
    }
}
